// pages/Auth/Register.jsx

import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';

function Register() {
  const navigate = useNavigate();
  const { register } = useContext(AuthContext);
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [password2, setPassword2] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    if (!username || !email || !password) return setError('필수 항목을 모두 입력하세요.');
    if (password !== password2) return setError('비밀번호가 일치하지 않습니다.');
    try {
      setLoading(true);
      await register({ username, email, password });
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.message || err.message || '회원가입 실패');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 520, margin: '40px auto', padding: 20, boxShadow: '0 6px 24px rgba(0,0,0,0.06)', borderRadius: 8 }}>
      <h2 style={{ marginBottom: 6 }}>새 계정 만들기</h2>
      <p style={{ color: '#666', marginTop: 0 }}>간단한 몇 단계로 회원가입을 완료하세요.</p>

      <form onSubmit={handleSubmit}>
        <label style={{ display: 'block', marginTop: 12 }}>
          <div style={{ fontSize: 13, color: '#333' }}>이름</div>
          <input value={username} onChange={(e) => setUsername(e.target.value)} style={{ width: '100%', padding: 10, marginTop: 6, borderRadius: 6, border: '1px solid #ddd' }} />
        </label>

        <label style={{ display: 'block', marginTop: 12 }}>
          <div style={{ fontSize: 13, color: '#333' }}>이메일</div>
          <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: '100%', padding: 10, marginTop: 6, borderRadius: 6, border: '1px solid #ddd' }} />
        </label>

        <label style={{ display: 'block', marginTop: 12 }}>
          <div style={{ fontSize: 13, color: '#333' }}>비밀번호</div>
          <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: 10, marginTop: 6, borderRadius: 6, border: '1px solid #ddd' }} />
        </label>

        <label style={{ display: 'block', marginTop: 12 }}>
          <div style={{ fontSize: 13, color: '#333' }}>비밀번호 확인</div>
          <input type="password" value={password2} onChange={(e) => setPassword2(e.target.value)} style={{ width: '100%', padding: 10, marginTop: 6, borderRadius: 6, border: '1px solid #ddd' }} />
        </label>

        {error && <div style={{ marginTop: 12, color: 'crimson' }}>{error}</div>}

        <button type="submit" disabled={loading} style={{ marginTop: 16, width: '100%', padding: 12, background: '#0070f3', color: '#fff', border: 'none', borderRadius: 8 }}>
          {loading ? '가입 중...' : '회원가입'}
        </button>
      </form>
    </div>
  );
}

export default Register;
